<script setup lang="ts">
import { ref, watch } from 'vue'
import { clone, api } from '../api'
import type { Configuration, Profile } from '../types'
const props = defineProps<{configuration:Configuration; editable:boolean}>()
const emit = defineEmits<{save:[configuration:Configuration]; error:[message:string]; health:[profile:string,status:string]}>()
const draft=ref<Configuration>(clone(props.configuration)), selected=ref(Object.keys(props.configuration.profiles)[0] ?? ''), name=ref('')
const discovered=ref<{name:string;chat_capable:boolean;size?:number}[]>([]), status=ref('not_tested'), busy=ref(false)
watch(() => props.configuration, v => {draft.value=clone(v)})
const profile = () => draft.value.profiles[selected.value]!
function add(){ if(!name.value.trim() || draft.value.profiles[name.value])return; const key=name.value.trim(); draft.value.profiles[key]={provider:'local',model:'qwen3:8b',base_url:'http://127.0.0.1:11434/v1',api_key_env:null,max_tokens:2048,temperature:0,timeout_seconds:120,retry_count:2,structured_output:'schema',local_server:'ollama'};selected.value=key;name.value='';discovered.value=[] }
async function discover(){busy.value=true;try{const data=await api<{status:string;models:typeof discovered.value}>(`/models/discover?profile=${encodeURIComponent(selected.value)}`); discovered.value=data.models;status.value=data.status}catch(e){emit('error',String(e))}finally{busy.value=false}}
async function test(){busy.value=true;try{const data=await api<{status:string}>(`/models/${encodeURIComponent(selected.value)}/test`,'POST');status.value=data.status;emit('health',selected.value,data.status)}catch(e){emit('error',String(e))}finally{busy.value=false}}
function save(){const clean=clone(draft.value); for(const p of Object.values(clean.profiles)){delete p.credential_configured;delete p.location}emit('save',clean)}
function providerChanged(p:Profile){p.api_key_env=({openai:'OPENAI_API_KEY',anthropic:'ANTHROPIC_API_KEY',local:'LOCAL_MODEL_API_KEY'} as Record<string,string>)[p.provider] || null;if(p.provider==='anthropic')p.temperature=null}
</script>
<template><div class="settings-grid"><section class="panel"><h2>Model profiles</h2><p class="muted">Local first. Mix providers by role.</p><button v-for="(_,key) in draft.profiles" :key="key" class="profile-item" :class="{selected:selected===key}" @click="selected=String(key);discovered=[];status='not_tested'">{{key}}<small>{{draft.profiles[key]?.provider}} / {{draft.profiles[key]?.model}}</small></button><div class="form-row"><input v-model="name" aria-label="New profile name" placeholder="New profile name" /><button :disabled="!editable" @click="add">Add</button></div><h3>Agent assignments</h3><label v-for="(a,role) in draft.agents" :key="role">{{role}}<select v-model="a.profile" :disabled="!editable"><option v-for="(_,key) in draft.profiles" :key="key">{{key}}</option></select></label></section><section class="panel" v-if="profile()"><div class="section-top"><h2>{{selected}}</h2><span class="badge">{{status.replaceAll('_',' ').toUpperCase()}}</span></div><fieldset :disabled="!editable"><div class="form-row"><label>Provider<select v-model="profile().provider" @change="providerChanged(profile())"><option value="local">Local / OpenAI compatible</option><option value="openai">OpenAI</option><option value="anthropic">Anthropic</option><option value="scripted">Scripted · offline demo</option></select></label><label v-if="profile().provider==='local'">Server<select v-model="profile().local_server"><option value="ollama">Ollama</option><option value="compatible">llama.cpp / LM Studio / vLLM</option></select></label></div><label v-if="profile().provider==='local'">Base URL<input v-model="profile().base_url" type="url" /></label><label>Model<input v-model="profile().model" list="installed-models" /><datalist id="installed-models"><option v-for="m in discovered.filter(m=>m.chat_capable)" :key="m.name" :value="m.name" /></datalist></label><div class="form-row"><label>Max output tokens<input v-model.number="profile().max_tokens" type="number" min="64" max="128000" /></label><label>Temperature (blank = provider default)<input v-model.number="profile().temperature" type="number" min="0" max="2" step="0.1" @change="profile().temperature=profile().temperature === ('' as unknown) ? null : profile().temperature" /></label></div><div class="form-row"><label>Timeout (seconds)<input v-model.number="profile().timeout_seconds" type="number" min="1" max="3600" /></label><label>Retry count<input v-model.number="profile().retry_count" type="number" min="0" max="5" /></label></div><label>Structured output<select v-model="profile().structured_output"><option value="schema">JSON schema</option><option value="json">JSON mode</option><option value="off">Validated parser fallback</option></select></label><label>Credential environment variable<input v-model="profile().api_key_env" placeholder="LOCAL_MODEL_API_KEY" /></label><p class="muted">{{configuration.profiles[selected]?.credential_configured ? '● Credential configured' : '○ Credential not configured'}} · Set secrets in the backend environment. Existing values are never returned.</p></fieldset><div class="actions"><button :disabled="busy || !configuration.profiles[selected]" @click="discover">Discover installed models</button><button :disabled="busy || !editable || !configuration.profiles[selected]" @click="test">{{busy?'Checking…':'Test saved connection'}}</button><button class="primary" :disabled="!editable" @click="save">Save configuration</button></div><p class="muted">Save edits before discovery or connection testing. Connection tests send one small model request.</p><ul v-if="discovered.length" class="model-list"><li v-for="m in discovered" :key="m.name">{{m.name}} <span class="muted">{{m.chat_capable?'Chat candidate':'Embedding · excluded from selection'}} {{m.size ? `· ${(m.size/1e9).toFixed(1)} GB` : ''}}</span></li></ul></section></div></template>
